    "Publicado" boolean NOT NULL,
    "EmpresaId" integer NOT NULL,
    "FechaCreacion" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PerfilesPublicos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PerfilesPublicos_Empresas_EmpresaId" FOREIGN KEY ("EmpresaId") REFERENCES "Empresas" ("Id") ON DELETE CASCADE
);

